-- experiments.lua -- ENGINE experiments: build a physical setup from a spec, release it, and record exactly
-- what Havok does. The Lua never judges anything. A spec (generated by stage/gmod/experiments from Mentat's
-- predictions, one file per scenario in lua/mentat/exp_specs/) carries Mentat's numbers; this file only
-- builds, runs and records. Grading is done independently in Python (stage/gmod/experiments/grade.py).
--
-- Interactive:  mentat_exp <id>   (S01, S02, ...)   mentat_exp_list   mentat_exp_clear
-- Headless:     data/mentat/experiment.txt = {"id":"S01","run_id":"r1","shots":true}  -> data/mentat/experiment_<id>.json
--
-- Frame: every spec position is metres in a LOCAL frame, x forward, y left, z up, origin on the floor at the
-- stage anchor, so an experiment is placed wherever there is clear flat space. Samples are recorded in that
-- same frame (metres, m/s, unit vectors), so Python needs no knowledge of where the stage landed.
if not SERVER then return end

local U = Mentat.units
local HU = Mentat.HU
local TAU = engine.TickInterval()
local Exp = { run = nil }
Mentat.Exp = Exp

-- ---------------------------------------------------------------- surfaces
-- MEASURED ENGINE LIMIT: physenv.AddSurfaceData honours only the FIRST surface a session adds. Later calls still hand
-- out an index, but the surface reads back as the default (friction 0.8, elasticity 0.25) and bodies keep "default".
-- So a scenario may define ONE custom surface (give it to the part whose friction or bounce is the free parameter) and
-- use the engine's stock surfaces (util.GetSurfaceData lists them) for everything else. Exp.Run refuses a spec that
-- asks for more, and the results record what the engine really applied.
local registered = {}
local custom_count = 0
local function surface_name(s)
  if s == nil then return "default" end
  if type(s) == "string" then return s end
  local name = string.format("mentat_s_%d_%d_%d", math.floor(s.friction * 1e4 + 0.5),
    math.floor(s.elasticity * 1e4 + 0.5), math.floor((s.density or 1000) + 0.5))
  if not registered[name] then
    custom_count = custom_count + 1
    if custom_count > 1 then
      error("a second custom surface was requested (" .. name .. "): the engine applies only the first (see surfaces note)")
    end
    physenv.AddSurfaceData(string.format(
      '"%s" { "base" "default" "density" "%g" "friction" "%.6f" "elasticity" "%.6f" "thickness" "0" "dampening" "0" }',
      name, s.density or 1000, s.friction, s.elasticity))
    registered[name] = true
  end
  return name
end

-- ---------------------------------------------------------------- the local frame
local function make_frame(anchor, yaw)
  local ang = Angle(0, yaw, 0)
  local f, l = ang:Forward(), -ang:Right()              -- Source's Right() is the right-hand vector
  local fr = { anchor = anchor, yaw = yaw, f = f, l = l }
  function fr.world(x, y, z) return anchor + f * (x * HU) + l * (y * HU) + Vector(0, 0, z * HU) end
  function fr.wvec(x, y, z) return f * (x * HU) + l * (y * HU) + Vector(0, 0, z * HU) end
  function fr.rot(v) return v:Dot(f), v:Dot(l), v.z end                   -- direction only, no scaling
  function fr.tolocal(p) local d = p - anchor; return d:Dot(f) / HU, d:Dot(l) / HU, d.z / HU end
  function fr.tolocalvec(v) return v:Dot(f) / HU, v:Dot(l) / HU, v.z / HU end
  function fr.wang(p, y, r) return Angle(p, y + yaw, r) end
  return fr
end

local function floor_at(pos)
  return util.TraceLine({ start = pos + Vector(0, 0, 64), endpos = pos - Vector(0, 0, 512), mask = MASK_SOLID_BRUSHONLY })
end

--- Where to look for space when nobody is connected (a dedicated server): the map's own player start.
local function map_origin()
  for _, cls in ipairs({ "info_player_start", "gmod_player_start", "info_player_teamspawn", "info_player_terrorist" }) do
    local e = ents.FindByClass(cls)[1]
    if IsValid(e) then return e:GetPos() end
  end
  return Vector(0, 0, 0)
end

--- Find clear, flat space for the box the experiment needs, starting near the player (or the map start if none).
local function pick_frame(ply, need)
  need = need or {}
  local nf, nl, nu = (need.forward_m or 4) * HU, (need.left_m or 3) * HU, (need.up_m or 4) * HU
  local origin = IsValid(ply) and ply:GetPos() or map_origin()
  local base = IsValid(ply) and ply:EyeAngles().y or 0
  local best, best_score
  for _, off in ipairs({ 0, 45, -45, 90, -90, 135, -135, 180 }) do
    local yaw = base + off
    local ang = Angle(0, yaw, 0)
    local f, l = ang:Forward(), -ang:Right()
    local tr = floor_at(origin + f * 120)
    if tr.Hit then
      local anchor = tr.HitPos
      local score, flat = 1, true
      for _, fx in ipairs({ 0, nf }) do
        for _, ly in ipairs({ -nl / 2, nl / 2 }) do
          local c = floor_at(anchor + f * fx + l * ly)
          if not c.Hit or math.abs(c.HitPos.z - anchor.z) > 3 then flat = false end
          for _, hz in ipairs({ 24, nu }) do
            local t = util.TraceLine({ start = anchor + Vector(0, 0, 24), endpos = anchor + f * fx + l * ly + Vector(0, 0, hz),
                                       mask = MASK_SOLID_BRUSHONLY })
            score = math.min(score, t.Fraction)
          end
        end
      end
      if flat then
        if score >= 1 then return anchor, yaw, true end
        if not best_score or score > best_score then best, best_score = { anchor, yaw }, score end
      end
    end
  end
  if best then return best[1], best[2], false end
  return origin, base, false
end

-- ---------------------------------------------------------------- building
local function dims_vector(def)
  local d = def.dims
  if def.shape == "sphere" then return Vector(d.radius, 0, 0) end
  if def.shape == "box" then return Vector(d.size[1], d.size[2], d.size[3]) end
  if def.shape == "cylinder" then return Vector(d.radius, d.height, 0) end
  if def.shape == "ring" then return Vector(d.outer_radius, d.inner_radius, d.height) end
  error("unknown shape " .. tostring(def.shape))
end

--- What the engine actually applies for a surface name: friction, elasticity, density (nil if unknown).
function Exp.surface_data(name)
  local idx = util.GetSurfaceIndex(name)
  local sd = idx and idx >= 0 and util.GetSurfaceData(idx)
  if not sd then return nil end
  return { friction = sd.friction, elasticity = sd.elasticity, density = sd.density }
end

local function spawn_prop(fr, def)
  local ent = ents.Create("mentat_prop")
  if not IsValid(ent) then error("ents.Create('mentat_prop') failed: is the addon mounted?") end
  ent:SetShape(def.shape)
  ent:SetDims(dims_vector(def))
  ent:SetSeg(def.dims.seg or 0)
  local c = def.color or { 0.7, 0.7, 0.7 }
  ent:SetTint(Vector(c[1], c[2], c[3]))
  ent.MentatDef = { surface = surface_name(def.surface), mass_kg = def.mass_kg, gravity = def.gravity,
                    damping_linear = def.damping_linear, damping_angular = def.damping_angular,
                    static = def.static, inertia_si = def.inertia_si }
  local p, a = def.pos_m, def.ang_deg or { 0, 0, 0 }
  ent:SetPos(fr.world(p[1], p[2], p[3]))
  ent:SetAngles(fr.wang(a[1], a[2], a[3]))
  ent:Spawn()
  ent:Activate()
  if not IsValid(ent) or ent:IsMarkedForDeletion() or not ent.MentatReady then
    local why = IsValid(ent) and ent.MentatError or "failed"
    if IsValid(ent) then ent:Remove() end
    error("prop '" .. tostring(def.id) .. "' not built: " .. tostring(why))
  end
  return ent
end

-- ---------------------------------------------------------------- HUD lines
local function hud(lines)
  for i = 1, 8 do SetGlobal2String("mentat_exp_l" .. i, lines[i] or "") end
end

-- ---------------------------------------------------------------- constraints
--- Build the spec's constraints once every body exists. A constraint names two bodies by id and the two attachment
--- points in the stage frame (metres, at the initial pose); the points are converted to each body's own axes.
---   rope    -> constraint.Rope, rigid (a pendulum string): the length is the distance between the points
---   elastic -> constraint.Elastic (a spring): rest length is the distance between the points; `constant` and
---              `damping` are handed over as given (the engine's own units; the grader measures what they became)
function Exp.build_constraints(r)
  local list = r.spec.constraints
  if not list then return end
  local by_id = {}
  for _, pr in ipairs(r.props) do by_id[pr.def.id] = pr.ent end
  r.constraint_info = {}
  for _, c in ipairs(list) do
    local ea, eb = by_id[c.a], by_id[c.b]
    if not (IsValid(ea) and IsValid(eb)) then error("constraint " .. tostring(c.kind) .. ": unknown body " .. tostring(c.a) .. " or " .. tostring(c.b)) end
    local pa = ea:WorldToLocal(r.fr.world(c.a_point_m[1], c.a_point_m[2], c.a_point_m[3]))
    local pb = eb:WorldToLocal(r.fr.world(c.b_point_m[1], c.b_point_m[2], c.b_point_m[3]))
    local ent
    if c.kind == "rope" then
      ent = constraint.Rope(ea, eb, 0, 0, pa, pb, 0, 0, 0, c.width or 1, c.material or "cable/cable", true)
    elseif c.kind == "elastic" then
      ent = constraint.Elastic(ea, eb, 0, 0, pa, pb, c.constant, c.damping or 0, c.rotation_damping or 0, c.material or "cable/cable",
                               c.width or 2, c.stretch_only and true or false)
    else
      error("unknown constraint kind " .. tostring(c.kind))
    end
    if not IsValid(ent) then error("constraint " .. c.kind .. " between " .. c.a .. " and " .. c.b .. " was not created") end
    r.constraint_info[#r.constraint_info + 1] = { kind = c.kind, a = c.a, b = c.b, class = ent:GetClass(), constant = c.constant, damping = c.damping }
  end
end

-- ---------------------------------------------------------------- lifecycle
function Exp.Clear()
  local r = Exp.run
  hook.Remove("Tick", "MentatExp")
  if r then
    for _, p in ipairs(r.props) do if IsValid(p.ent) then p.ent:Remove() end end
    if r.saved_gravity then physenv.SetGravity(r.saved_gravity) end
  end
  Exp.run = nil
  hud({})
end

local function load_spec(id)
  local path = "mentat/exp_specs/" .. string.lower(id) .. ".lua"
  if not file.Exists(path, "LUA") then return nil, "no spec " .. path .. " (python stage/gmod/experiments/build.py)" end
  local ok, spec = pcall(include, path)
  if not ok or type(spec) ~= "table" then return nil, "spec failed to load: " .. tostring(spec) end
  return spec
end

--- A dedicated-server run has nothing left to do once the result is written: ask the server to exit.
function Exp.quit_now()
  timer.Simple(2, function()
    print("[mentat-exp] result written; shutting the server down")
    game.ConsoleCommand("quit" .. string.char(10))
  end)
end

local function write_result(r)
  local out = {
    id = r.spec.id, run_id = r.opts.run_id, spec_sha = r.spec.sha, spec_version = r.spec.version,
    tick = TAU, gravity_hu = r.gravity_hu, anchor = { r.fr.anchor.x, r.fr.anchor.y, r.fr.anchor.z },
    yaw = r.fr.yaw, frame_clear = r.frame_clear, map = game.GetMap(), version = Mentat.VERSION, dedicated = game.IsDedicated(),
    props = r.prop_info, constraints = r.constraint_info, samples = r.samples, live = r.live, shots = r.shots, error = r.error, finished = true,
  }
  file.CreateDir("mentat")
  local path = "mentat/experiment_" .. r.spec.id .. ".json"
  file.Write(path, util.TableToJSON(out))
  print("[mentat-exp] wrote data/" .. path .. " (" .. #r.samples .. " samples)")
  if Exp.quit_after_result then Exp.quit_now() end
end

local function sample(r)
  local k = r.k
  local row = { k = k, ct = CurTime(), p = {} }
  for i, pr in ipairs(r.props) do
    local ent = pr.ent
    local phys = ent:GetPhysicsObject()
    -- Everything is read from the physics object itself.
    local x, y, z = r.fr.tolocal(phys:GetPos())
    local vx, vy, vz = r.fr.tolocalvec(phys:GetVelocity())
    local ang = phys:GetAngles()
    local fx, fy, fz = r.fr.rot(ang:Forward())
    local ux, uy, uz = r.fr.rot(ang:Up())
    local w = phys:GetAngleVelocity()                     -- deg/s in the body's LOCAL axes (measured semantics)
    row.p[i] = { x, y, z, vx, vy, vz, fx, fy, fz, ux, uy, uz, w.x, w.y, w.z }
  end
  r.samples[#r.samples + 1] = row
end

--- Drag and damping as the engine reports them now (for the record: are the settings still what we set?).
local function flags(pr)
  local phys = pr.ent:GetPhysicsObject()
  local okd, drag = pcall(function() return phys:IsDragEnabled() end)
  local lin, ang = phys:GetDamping()
  return { drag = okd and drag or "unknown", damping_linear = lin, damping_angular = ang, asleep = phys:IsAsleep(),
           gravity = phys:IsGravityEnabled() }
end

--- Release is ONE tick: the bodies are awake (see hold), so the velocity set here is not discarded. Sample k=0 is
--- taken right after it. With the half-step "kick" below the engine's positions follow the exact continuous
--- trajectory z0 + v0 t - g t^2 / 2 to 1e-5 m, from t = k tau in the game client and from t = (k - 1) tau on a dedicated
--- server (there the engine moves a body with the velocity it had before this hook, so the first tick is empty; the
--- result records `dedicated` and the grader shifts its clock).
local function release_go(r)
  local kick = Vector(0, 0, -r.gravity_hu.z * TAU / 2)
  for _, pr in ipairs(r.props) do
    local def = pr.def
    if not def.static then
      local phys = pr.ent:GetPhysicsObject()
      pr.asleep_before = phys:IsAsleep()
      local v = def.v0_m_s or { 0, 0, 0 }
      local vw = r.fr.wvec(v[1], v[2], v[3])
      -- Havok integrates v += a*dt then x += v*dt. Starting a body at the true velocity therefore makes it
      -- fall as if released tau/2 early (measured). Adding the half-step velocity -a*tau/2 makes the
      -- engine's positions at every tick equal the exact continuous trajectory.
      if def.gravity ~= false and def.kick ~= false then vw = vw + kick end
      phys:EnableGravity(def.gravity ~= false)
      phys:Wake()
      phys:SetVelocity(vw)
      phys:SetAngleVelocityInstantaneous(Vector(0, 0, 0))
      pr.flags_release = flags(pr)
    end
  end
end

local function finish(r)
  hook.Remove("Tick", "MentatExp")
  r.phase = "done"
  for i, pr in ipairs(r.props) do
    if r.prop_info[i] and not pr.def.static then r.prop_info[i].flags_release, r.prop_info[i].flags_end = pr.flags_release, flags(pr)
      r.prop_info[i].asleep_before_release = pr.asleep_before end
  end
  local ok, live = pcall(Exp.live_readouts, r)
  r.live = ok and live or { error = tostring(live) }
  local lines = { "MENTAT ENGINE EXPERIMENT " .. r.spec.id .. ": " .. r.spec.name .. "   (Havok measured vs Mentat predicted)" }
  for _, ln in ipairs((ok and live.lines) or {}) do lines[#lines + 1] = ln end
  if not r.frame_clear then lines[#lines + 1] = "warning: the stage may be obstructed by the map; results may be off" end
  hud(lines)
  if r.opts.shots then r.shot("end") end
  timer.Simple(r.opts.shots and 1.0 or 0, function() write_result(r) end)
end

--- Before release every free body is held on its spec pose: awake, weightless, motionless in translation, and
--- TURNING: it spins about its own up axis for exactly `hold_ticks` ticks at a rate chosen so the total is a whole
--- number of turns, which puts it back on its exact orientation without ever re-posing it. The release (the tick
--- after the last spin step) switches the spin off.
---
--- Why: the physics engine gives a body that is awake but nearly motionless an extra 0.1/s linear damping that no
--- setting removes (GetDamping still reads what we set). When such a body is released the damping stays on for a
--- body-specific number of ticks (measured 0 to 47, deterministic per body and per scene, ending abruptly), which
--- slows a fall by up to 5 %. A body that keeps turning is not in that state, as long as it is never teleported
--- (re-posing it with SetPos/SetAngles brings the damping back) and the turning does not reverse (a back-and-forth
--- wobble only protects some bodies). Measured: no transient on any body from about 100 deg/s upward.
local HOLD_SPIN_DEG_S = 720

--- Spin rate (deg/s) giving a whole number of turns over `ticks` ticks, at least `min_rate`.
local function hold_rate(ticks, min_rate)
  local turns = math.max(1, math.floor(min_rate * ticks * TAU / 360 + 0.5))
  return 360 * turns / (ticks * TAU)
end

local function hold(r, final)
  for _, pr in ipairs(r.props) do
    if not pr.def.static then
      local phys = pr.ent:GetPhysicsObject()
      phys:EnableGravity(false)
      phys:SetVelocity(Vector(0, 0, 0))
      local spin = final and 0 or hold_rate(r.hold_ticks, pr.def.hold_spin_deg_s or HOLD_SPIN_DEG_S)
      phys:SetAngleVelocityInstantaneous(Vector(0, 0, spin))
      phys:Wake()
    end
  end
  if not final then r.spin_n = r.spin_n + 1 end
end

local function step(r)
  if r.phase == "settle" then
    local final = r.spin_n >= r.hold_ticks
    hold(r, final)
    if final then
      release_go(r)
      r.phase, r.k = "run", 0
      sample(r)
      if r.opts.shots then r.shot("release") end
    end
  elseif r.phase == "run" then
    r.k = r.k + 1
    sample(r)
    if r.opts.shots and not r.took_mid and r.k * TAU >= r.spec.timeline.run_s * 0.5 then
      r.took_mid = true
      r.shot("mid")
    end
    if r.k * TAU >= r.spec.timeline.run_s then finish(r) end
  end
end

--- Run experiment `id` near `ply`. opts: { run_id, shots }.
function Exp.Run(id, ply, opts)
  Exp.Clear()
  opts = opts or {}
  local spec, err = load_spec(id)
  if not spec then return false, err end

  local r = { spec = spec, opts = opts, props = {}, prop_info = {}, samples = {}, shots = {}, phase = "settle", k = 0, spin_n = 0 }
  r.hold_ticks = math.max(2, math.ceil(spec.timeline.settle_s / TAU))
  r.saved_gravity = physenv.GetGravity()
  r.gravity_hu = { x = 0, y = 0, z = -spec.gravity_m_s2 * HU }
  physenv.SetGravity(Vector(0, 0, r.gravity_hu.z))
  Exp.run = r

  local anchor, yaw, clear = pick_frame(ply, spec.needs)
  r.fr, r.frame_clear = make_frame(anchor, yaw), clear
  local okb, errb = pcall(function()
    for _, def in ipairs(spec.props) do surface_name(def.surface) end      -- register every surface before any body is built
    for _, def in ipairs(spec.props) do
      local ent = spawn_prop(r.fr, def)
      r.props[#r.props + 1] = { ent = ent, def = def, home_pos = ent:GetPos(), home_ang = ent:GetAngles() }
      local phys = ent:GetPhysicsObject()
      r.prop_info[#r.prop_info + 1] = { id = def.id, mass_kg = phys:GetMass(), static = def.static or false,
                                        surface = ent.MentatDef.surface, engine_material = phys:GetMaterial(),
                                        engine_surface = Exp.surface_data(phys:GetMaterial()), shape = def.shape,
                                        inertia_raw = { phys:GetInertia().x, phys:GetInertia().y, phys:GetInertia().z },
                                        mass_center_raw = { phys:GetMassCenter().x, phys:GetMassCenter().y, phys:GetMassCenter().z } }
    end
    if Exp.build_constraints then Exp.build_constraints(r) end
  end)
  if not okb then
    Exp.Clear()
    return false, tostring(errb)
  end
  r.t0 = CurTime()
  hud({ "MENTAT ENGINE EXPERIMENT " .. spec.id .. ": " .. spec.name .. "  (setting up, release in "
        .. string.format("%.1f", spec.timeline.settle_s) .. " s)" })
  r.shot = function(tag)                                  -- screenshot with the camera aimed at the experiment
    if IsValid(ply) then ply:SetEyeAngles((r.fr.world(spec.focus_m[1], spec.focus_m[2], spec.focus_m[3]) - ply:EyePos()):Angle()) end
    Mentat.Shot("exp_" .. spec.id .. "_" .. tag)
    r.shots[#r.shots + 1] = tag
  end
  if opts.shots and IsValid(ply) then r.shot("setup") end
  hook.Add("Tick", "MentatExp", function()
    local ok, e = pcall(step, r)
    if not ok then
      r.error = tostring(e)
      hook.Remove("Tick", "MentatExp")
      write_result(r)
    end
  end)
  return true
end

-- ---------------------------------------------------------------- live readouts (display only)
-- Convenience for the person watching: a few measured quantities next to Mentat's prediction. These are NOT the
-- grade (the Python grader recomputes everything from the raw samples and also checks these agree).
local function prop_index(r, id)
  for i, pr in ipairs(r.props) do if pr.def.id == id then return i end end
end

Exp.live = {}

--- Time (s since release) at which a prop's height first falls through lv.z_m.
function Exp.live.gate_time(r, lv)
  local i = prop_index(r, lv.prop)
  local prev
  for _, row in ipairs(r.samples) do
    local z = row.p[i][3]
    if prev and prev.z > lv.z_m and z <= lv.z_m then
      return (prev.k + (prev.z - lv.z_m) / (prev.z - z)) * TAU
    end
    prev = { k = row.k, z = z }
  end
end

--- Height gained above the launch point (m).
function Exp.live.apex(r, lv)
  local i = prop_index(r, lv.prop)
  local z0, zmax = r.spec.props[i].pos_m[3], -math.huge
  for _, row in ipairs(r.samples) do zmax = math.max(zmax, row.p[i][3]) end
  return zmax - z0
end

--- Where a prop comes back down through its launch height: returns time (s) and horizontal distance (m).
local function return_crossing(r, lv)
  local i = prop_index(r, lv.prop)
  local z0, prev, up = r.spec.props[i].pos_m[3], nil, false
  for _, row in ipairs(r.samples) do
    local z, x = row.p[i][3], row.p[i][1]
    if z > z0 + 1e-3 then up = true end
    if up and prev and prev.z > z0 and z <= z0 then
      local u = (prev.z - z0) / (prev.z - z)
      return (prev.k + u) * TAU, prev.x + (x - prev.x) * u
    end
    prev = { k = row.k, z = z, x = x }
  end
end
function Exp.live.return_time(r, lv) local t = return_crossing(r, lv); return t end
function Exp.live.range_at_return(r, lv) local _, x = return_crossing(r, lv); return x - r.spec.props[prop_index(r, lv.prop)].pos_m[1] end

function Exp.live_readouts(r)
  local lines, values = {}, {}
  for _, lv in ipairs(r.spec.live or {}) do
    local fn = Exp.live[lv.kind]
    local ok, v = false, nil
    if fn then ok, v = pcall(fn, r, lv) end
    values[#values + 1] = { label = lv.label, kind = lv.kind, measured = ok and v or nil, predicted = lv.predicted }
    if ok and v then
      lines[#lines + 1] = string.format("%-28s Havok %.5f %s   Mentat %.5f %s   (%+.3f %%)", lv.label, v, lv.units,
        lv.predicted, lv.units, 100 * (v - lv.predicted) / lv.predicted)
    else
      lines[#lines + 1] = lv.label .. ": no reading"
    end
  end
  return { lines = lines, values = values }
end

-- ---------------------------------------------------------------- console
local function admin_only(ply) return not IsValid(ply) or ply:IsAdmin() or game.SinglePlayer() end
local function say(ply, msg) if IsValid(ply) then ply:PrintMessage(HUD_PRINTCONSOLE, msg .. "\n") else print(msg) end end

concommand.Add("mentat_exp", function(ply, _, args)
  if not admin_only(ply) then return end
  if not args[1] then return say(ply, "usage: mentat_exp <id>   e.g. mentat_exp S01   (mentat_exp_list)") end
  if not IsValid(ply) then return say(ply, "[mentat-exp] needs a player: run it in game") end
  local ok, err = Exp.Run(args[1]:upper(), ply, {})
  say(ply, ok and ("[mentat-exp] running " .. args[1]:upper()) or ("[mentat-exp] failed: " .. tostring(err)))
end)
concommand.Add("mentat_exp_clear", function(ply) if admin_only(ply) then Exp.Clear() end end)
concommand.Add("mentat_exp_list", function(ply)
  if not admin_only(ply) then return end
  local names = {}
  for _, f in ipairs((file.Find("mentat/exp_specs/*.lua", "LUA"))) do names[#names + 1] = string.upper((f:gsub("%.lua$", ""))) end
  say(ply, "[mentat-exp] " .. table.concat(names, ", "))
end)

-- ---------------------------------------------------------------- headless trigger
-- data/mentat/experiment.txt = {"id":"S01","run_id":"r1","shots":false,"quit":true}
--   listen server / game window : runs 5 s after the local player spawns
--   dedicated server (no players): runs 5 s after the map has loaded; "quit" shuts the server down afterwards
local CFG = "mentat/experiment.txt"
if file.Exists(CFG, "DATA") then
  local cfg = util.JSONToTable(file.Read(CFG, "DATA") or "")
  file.Delete(CFG)
  if type(cfg) == "table" and type(cfg.id) == "string" and cfg.id:match("^S%d+$") then
    file.CreateDir("mentat")
    file.Delete("mentat/experiment_" .. cfg.id .. ".json")        -- a stale result must never pass for a fresh run
    local function go(ply)
      local ok, err = Exp.Run(cfg.id, ply, { run_id = cfg.run_id, shots = cfg.shots })
      if not ok then
        file.Write("mentat/experiment_" .. cfg.id .. ".json", util.TableToJSON({ id = cfg.id, run_id = cfg.run_id,
          error = tostring(err), finished = true, samples = {} }))
        print("[mentat-exp] run failed: " .. tostring(err))
        if Exp.quit_after_result then Exp.quit_now() end
      end
    end
    if game.IsDedicated() then
      Exp.quit_after_result = cfg.quit and true or false
      hook.Add("InitPostEntity", "MentatExpRun", function()
        timer.Simple(5, function() go(nil) end)
      end)
    else
      hook.Add("PlayerInitialSpawn", "MentatExpRun", function(ply)
        timer.Simple(5, function() if IsValid(ply) then go(ply) end end)
      end)
    end
    print("[mentat-exp] armed for " .. cfg.id .. " (run_id " .. tostring(cfg.run_id) .. ")" .. (game.IsDedicated() and " on a dedicated server" or ""))
  else
    print("[mentat-exp] unreadable experiment.txt; ignored")
  end
end
